import icontract
from typing import List


@icontract.ensure(lambda a, result: len(result) == len(a) + 1)
@icontract.ensure(lambda a, result: len(result) == len(a) + 1 and all(result[i] == a[i] for i in range(len(a))))
@icontract.ensure(lambda a, b, result: len(result) == len(a) + 1 and result[len(a)] == b)
def append(a: List[int], b: int) -> List[int]:
    result = []
    for x in a:
        result.append(x)
    result.append(b)
    return result
